-- Importación de los datos rescatados del Tuki original.
-- Generado a partir de Desktop/Tuki/rescate.
-- Ejecutar contra el PostgreSQL de producción con:
--   psql -U tuki_admin -d postgres -f db/importacion/importar-produccion.sql
--
-- Es idempotente: las filas existentes no se duplican ni se sobrescriben.
-- Las imágenes ya están subidas a RustFS por el script de rescate.

set client_encoding = 'UTF8';

-- Base pública de los objetos del bucket. El importador la inyecta con
-- `-v tuki_media_url=...`; este valor es solo el respaldo para ejecutar el
-- archivo a mano.
\if :{?tuki_media_url}
\else
\set tuki_media_url 'http://localhost:8084/tuki-media'
\endif

